using System.ComponentModel;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Agents.AI;

var builder = Host.CreateApplicationBuilder(args);

var apiKey = builder.Configuration["AI:ApiKey"]
    ?? Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set AI:ApiKey in configuration or OPENAI_API_KEY environment variable.");

var modelId = builder.Configuration["AI:ModelId"] ?? "gpt-4o-mini-2024-07-18";

builder.Services.AddChatClient(b => b
    .UseOpenAIChatClient(modelId, new OpenAI.OpenAIClient(apiKey)));

var host = builder.Build();

var chatClient = host.Services.GetRequiredService<IChatClient>();

// Register tools
var notepad = new Notepad();
var tools = new[]
{
    AIFunctionFactory.Create(WebSearchTool.SearchWeb),
    AIFunctionFactory.Create(notepad.AddNote),
    AIFunctionFactory.Create(notepad.GetNotes),
};

// Create the research agent
var agent = new ChatClientAgent(chatClient, "ResearchAgent")
{
    Instructions = """
        You are a research agent. Given a topic, you search the web to find relevant 
        information and take notes on key findings. After gathering enough information,
        provide a comprehensive summary of your research.

        Workflow:
        1. Search the web for the topic using different relevant queries.
        2. Take notes on important findings from each search.
        3. Once you have enough information, retrieve your notes and write a final summary.
        """,
    Tools = tools,
};

// Get topic from user
Console.Write("Enter a research topic: ");
var topic = Console.ReadLine()?.Trim();
if (string.IsNullOrEmpty(topic))
{
    Console.WriteLine("No topic provided. Exiting.");
    return;
}

Console.WriteLine($"\nResearching: {topic}\n");

var history = new List<ChatMessage>
{
    new(ChatRole.User, $"Research the following topic and provide a summary: {topic}"),
};

var options = new AgentInvokeOptions
{
    MaximumIterations = 10,
};

await foreach (var message in agent.InvokeStreamingAsync(history, options))
{
    if (message.Role == ChatRole.Assistant && !string.IsNullOrEmpty(message.Text))
    {
        Console.Write(message.Text);
    }
}

Console.WriteLine();

// --- Tools ---

/// <summary>Simulated web search tool that returns placeholder results.</summary>
static class WebSearchTool
{
    [Description("Searches the web for a query and returns relevant results.")]
    public static string SearchWeb(
        [Description("The search query to look up on the web.")] string query)
    {
        // In production, integrate with a real search API (Bing, Google, etc.)
        return $"""
            Search results for: "{query}"

            1. [Wikipedia] Overview article covering key aspects of {query}.
               Summary: Provides foundational context and historical background.

            2. [Research Paper] Recent study on {query} (2025).
               Summary: New findings suggest significant developments in this area.

            3. [News Article] Latest developments in {query}.
               Summary: Industry experts weigh in on current trends and future outlook.
            """;
    }
}

/// <summary>Note-taking tool that stores research findings.</summary>
class Notepad
{
    private readonly List<string> _notes = [];

    [Description("Adds a research note to the notepad for later reference.")]
    public string AddNote(
        [Description("The note content to save.")] string note)
    {
        _notes.Add(note);
        return $"Note #{_notes.Count} saved successfully.";
    }

    [Description("Retrieves all saved research notes.")]
    public string GetNotes()
    {
        if (_notes.Count == 0)
            return "No notes have been saved yet.";

        return string.Join("\n\n", _notes.Select((n, i) => $"Note #{i + 1}: {n}"));
    }
}

